const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const orlando = ee.Geometry.Point([-81.3792, 28.5383]);
    const aoi = orlando.buffer(25000); // 25km buffer around Orlando
    const startYear = 1985;
    const endYear = 2014;

    // Function to calculate NDBI and classify urban areas
    const classifyUrban = function(image) {
        // NDBI = (SWIR1 - NIR) / (SWIR1 + NIR)
        const ndbi = image.normalizedDifference(['SWIR1', 'NIR']).rename('NDBI');
        // Simple thresholding: NDBI > 0 is often considered built-up
        const urban = ndbi.gt(0).rename('urban');
        return image.addBands(urban);
    };

    // Function to mask clouds based on the QA band
    const maskL457sr = (image) => {
        const qa = image.select('pixel_qa');
        // Bits 3 and 5 are cloud shadow and cloud, respectively.
        const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 3));
        // Remove edge pixels that don't represent the full sensor snapshot
        const mask2 = image.mask().reduce(ee.Reducer.min());
        return image.updateMask(cloud.not()).updateMask(mask2);
    };

    const maskL8sr = (image) => {
        const qa = image.select('pixel_qa');
        // Bits 3 and 5 are cloud shadow and cloud, respectively.
        const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 3));
        return image.updateMask(cloud.not());
    };

    // 2. Data Acquisition & Check
    // Using Landsat 5 for the early period as it has the required SWIR band for NDBI.
    const collection1985 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
        .filterBounds(aoi)
        .filterDate(`${startYear}-01-01`, `${startYear}-12-31`)
        .map(maskL457sr);

    const collection2014 = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
        .filterBounds(aoi)
        .filterDate(`${endYear}-01-01`, `${endYear}-12-31`)
        .map(maskL8sr);

    const count1985 = collection1985.size().getInfo();
    const count2014 = collection2014.size().getInfo();

    if (count1985 === 0 || count2014 === 0) {
        console.log(`Image count 1985: ${count1985}`);
        console.log(`Image count 2014: ${count2014}`);
        console.log("C1: Empty Collection. Could not find images for one or both dates.");
        return;
    }

    // 3. Processing
    // Create median composites and rename bands for consistency
    const image1985 = collection1985.median().select(
        ['B5', 'B4'], // SWIR1, NIR for Landsat 5
        ['SWIR1', 'NIR']
    );
    const image2014 = collection2014.median().select(
        ['B6', 'B5'], // SWIR1, NIR for Landsat 8
        ['SWIR1', 'NIR']
    );

    const urban1985 = classifyUrban(image1985).select('urban');
    const urban2014 = classifyUrban(image2014).select('urban');

    // 4. Calculation
    // Calculate the area of urban pixels. The reducer sums the binary 'urban' mask.
    // The result is multiplied by the pixel area to get total area in square meters.
    const scale = 100; // Use a moderate scale to balance accuracy and performance
    const pixelArea = ee.Number(scale).pow(2);

    const urbanArea1985 = urban1985.multiply(pixelArea).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
    });

    const urbanArea2014 = urban2014.multiply(pixelArea).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
    });

    const area1985_sq_km = ee.Number(urbanArea1985.get('urban')).divide(1e6).getInfo();
    const area2014_sq_km = ee.Number(urbanArea2014.get('urban')).divide(1e6).getInfo();

    // 5. Validation & Final Answer
    if (area1985_sq_km === null || area2014_sq_km === null) {
        console.log(`1985 Area (km2): ${area1985_sq_km}`);
        console.log(`2014 Area (km2): ${area2014_sq_km}`);
        console.log("C3: Calculation Failure. Area calculation resulted in null.");
        return;
    }

    if (area1985_sq_km === 0 || area2014_sq_km === 0) {
        console.log(`1985 Area (km2): ${area1985_sq_km.toFixed(2)}`);
        console.log(`2014 Area (km2): ${area2014_sq_km.toFixed(2)}`);
        console.log("C2: No Valid Pixels. After masking, no urban pixels were detected in one period.");
        return;
    }

    console.log(`Image count 1985: ${count1985}`);
    console.log(`Image count 2014: ${count2014}`);
    console.log(`Estimated urban area in 1985: ${area1985_sq_km.toFixed(2)} km2`);
    console.log(`Estimated urban area in 2014: ${area2014_sq_km.toFixed(2)} km2`);

    if (area2014_sq_km > area1985_sq_km) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D");
});
